sections.body:
1. Consumer sends FETCH with {partition, offset}
2. Leader reads from page cache (zero-copy sendfile to socket)
3. Returns batch up to max.partition.fetch.bytes, only up to HW

steps.codeOrCommand:
// Producer-side
record = ProducerRecord( topic="orders", key="order-98765", value=<1 KB protobuf>
)
partition = murmur2(record.key) % 20 // = 7
accumulator["orders-7"].add(record)
// When batch full or linger.ms elapsed:
socket = connections[leader_of("orders-7")] // broker-12
socket.send(PRODUCE_REQUEST, records=batch, acks=-1)

// Consumer assigned partition orders-7
// Committed offset from last run = 8821339900
resp = fetch( broker=leader_of("orders-7"), // broker-12 partition="orders-7", offset=8821339900, max_bytes=1048576, max_wait_ms=500
)

# group coordinator handles it
commit_record = { key: ("g_order_processor", "orders", 7), value: { offset: 8821340143, metadata: "", ts: now }
}
produce_internal("__consumer_offsets", commit_record)

// Next iteration
resp = fetch(broker-12, "orders-7", offset=8821340143, max_wait_ms=500)
// Often returns empty until next producer batch arrives
